class Solution {
    public int[] canSee(int[] heights) {
        int n = heights.length;
        int[] res = new int[n];
        for (int i = 0; i < n; i++) {
            int tallest = 0;
            for (int j = i + 1; j < n; j++) {
                if (tallest < Math.min(heights[i], heights[j])) res[i]++;
                tallest = Math.max(tallest, heights[j]);
                if (tallest >= heights[i]) break;
            }
        }
        return res;
    }
}

