int* canSee(int* heights, int heightsSize, int* returnSize) {
    int n = heightsSize;
    int* res = calloc(n, sizeof(int));
    for (int i = 0; i < n; i++) {
        int tallest = 0;
        for (int j = i + 1; j < n; j++) {
            int lower = heights[i] < heights[j] ? heights[i] : heights[j];
            if (tallest < lower) res[i]++;
            if (heights[j] > tallest) tallest = heights[j];
            if (tallest >= heights[i]) break;
        }
    }
    *returnSize = n;
    return res;
}

