class Solution:
    def canSee(self, heights: List[int]) -> List[int]:
        n = len(heights)
        res, stack = [0] * n, []
        for i in range(n - 1, -1, -1):
            h = heights[i]
            while stack and stack[-1] < h:
                stack.pop()
                res[i] += 1
            if stack:
                res[i] += 1
                if stack[-1] == h:
                    stack.pop()
            stack.append(h)
        return res

