class Solution {
    public int[] canSee(int[] heights) {
        int n = heights.length;
        int[] res = new int[n], stack = new int[n];
        int top = 0;
        for (int i = n - 1; i >= 0; i--) {
            int h = heights[i];
            while (top > 0 && stack[top - 1] < h) { top--; res[i]++; }
            if (top > 0) {
                res[i]++;
                if (stack[top - 1] == h) top--;
            }
            stack[top++] = h;
        }
        return res;
    }
}

