class Solution {
public:
    vector<int> canSee(vector<int>& heights) {
        int n = heights.size();
        vector<int> res(n, 0), stack;
        for (int i = n - 1; i >= 0; i--) {
            int h = heights[i];
            while (!stack.empty() && stack.back() < h) { stack.pop_back(); res[i]++; }
            if (!stack.empty()) {
                res[i]++;
                if (stack.back() == h) stack.pop_back();
            }
            stack.push_back(h);
        }
        return res;
    }
};

