    int* res = calloc(n, sizeof(int));
    int* stack = malloc(n * sizeof(int));
    int top = 0;
    for (int i = n - 1; i >= 0; i--) {
        int h = heights[i];
        while (top > 0 && stack[top - 1] < h) { top--; res[i]++; }
        if (top > 0) {
            res[i]++;
            if (stack[top - 1] == h) top--;
        }
        stack[top++] = h;
    }
    free(stack);
    *returnSize = n;
    return res;
